// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 d) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= d);
        vm.assume(d > 0);
        uint before = address(c).balance;
        try c.deposit{value: d}() {} catch { return; }
        assertTrue(address(c).balance == before + d);
    }

    function testFuzz_run(uint256 d) public {
        _run(d);
    }

    receive() external payable {}
}
